import { z } from "zod/v4";
//#region src/routes/dashboard/deliveries/schema.ts
/** Admin editor form for a delivery. Deliveries are generated from a subscription — admins only edit them. */
var deliverySchema = z.object({
	id: z.string().min(1),
	status: z.enum([
		"scheduled",
		"dispatched",
		"delivered",
		"skipped",
		"failed"
	]),
	scheduledDate: z.string().min(1, { error: "Pick a date." }),
	isActive: z.boolean().default(true)
});
//#endregion
export { deliverySchema as t };
